
const BOARD_THEME_PRESETS = {
    'wood_walnut': { light: '#f0d9b5', dark: '#b58863', texture: 'wood' },
    'emerald_marble': { light: '#e2ebd8', dark: '#059669', texture: 'marble' },
    'glassmorphism': { light: '#c0d6df', dark: '#4a6fa5', texture: 'glass' },
    'cyber_neon': { light: '#1e1b4b', dark: '#4338ca', texture: 'none' },
    'slate_dark': { light: '#94a3b8', dark: '#334155', texture: 'none' },
    'classic_green': { light: '#ffffdd', dark: '#86a666', texture: 'none' }
};


// Web Audio API Synthesizer for Chess Sound FX
const chessAudioEngine = {
    ctx: null,
    getContext() {
        try {
            if (!this.ctx) {
                const AudioCtx = window.AudioContext || window.webkitAudioContext;
                if (AudioCtx) this.ctx = new AudioCtx();
            }
            if (this.ctx && this.ctx.state === 'suspended') this.ctx.resume();
            return this.ctx;
        } catch { return null; }
    },
    playMove(soundPack = 'classic_wood', volume = 0.8) {
        if (!gameSettings.enableSound || soundPack === 'silent' || volume <= 0) return;
        const ctx = this.getContext();
        if (!ctx) return;
        const now = ctx.currentTime;
        const master = ctx.createGain();
        master.gain.setValueAtTime(volume * 0.7, now);
        master.connect(ctx.destination);

        if (soundPack === 'classic_wood') {
            const osc = ctx.createOscillator();
            const gain = ctx.createGain();
            osc.type = 'triangle';
            osc.frequency.setValueAtTime(280, now);
            osc.frequency.exponentialRampToValueAtTime(120, now + 0.06);
            gain.gain.setValueAtTime(1.0, now);
            gain.gain.exponentialRampToValueAtTime(0.001, now + 0.06);
            osc.connect(gain); gain.connect(master);
            osc.start(now); osc.stop(now + 0.07);
        } else if (soundPack === 'digital_arcade') {
            const osc = ctx.createOscillator();
            const gain = ctx.createGain();
            osc.type = 'square';
            osc.frequency.setValueAtTime(600, now);
            osc.frequency.setValueAtTime(900, now + 0.03);
            gain.gain.setValueAtTime(0.4, now);
            gain.gain.exponentialRampToValueAtTime(0.01, now + 0.07);
            osc.connect(gain); gain.connect(master);
            osc.start(now); osc.stop(now + 0.07);
        } else {
            const osc = ctx.createOscillator();
            const gain = ctx.createGain();
            osc.type = 'sine';
            osc.frequency.setValueAtTime(1200, now);
            gain.gain.setValueAtTime(0.5, now);
            gain.gain.exponentialRampToValueAtTime(0.01, now + 0.06);
            osc.connect(gain); gain.connect(master);
            osc.start(now); osc.stop(now + 0.07);
        }
    },
    playCapture(soundPack = 'classic_wood', volume = 0.8) {
        if (!gameSettings.enableSound || soundPack === 'silent' || volume <= 0) return;
        const ctx = this.getContext();
        if (!ctx) return;
        const now = ctx.currentTime;
        const master = ctx.createGain();
        master.gain.setValueAtTime(volume * 0.9, now);
        master.connect(ctx.destination);
        [0, 0.02].forEach((offset) => {
            const osc = ctx.createOscillator();
            const gain = ctx.createGain();
            osc.type = 'triangle';
            osc.frequency.setValueAtTime(360 - offset * 2000, now + offset);
            osc.frequency.exponentialRampToValueAtTime(100, now + offset + 0.08);
            gain.gain.setValueAtTime(1.0, now + offset);
            gain.gain.exponentialRampToValueAtTime(0.001, now + offset + 0.08);
            osc.connect(gain); gain.connect(master);
            osc.start(now + offset); osc.stop(now + offset + 0.09);
        });
    },
    playCheck(soundPack = 'classic_wood', volume = 0.8) {
        if (!gameSettings.enableSound || soundPack === 'silent' || volume <= 0) return;
        const ctx = this.getContext();
        if (!ctx) return;
        const now = ctx.currentTime;
        const master = ctx.createGain();
        master.gain.setValueAtTime(volume, now);
        master.connect(ctx.destination);
        [523.25, 659.25].forEach((freq, i) => {
            const osc = ctx.createOscillator();
            const gain = ctx.createGain();
            osc.type = 'sine';
            osc.frequency.setValueAtTime(freq, now + i * 0.08);
            gain.gain.setValueAtTime(0.6, now + i * 0.08);
            gain.gain.exponentialRampToValueAtTime(0.001, now + i * 0.08 + 0.25);
            osc.connect(gain); gain.connect(master);
            osc.start(now + i * 0.08); osc.stop(now + i * 0.08 + 0.26);
        });
    },
    playBlunder(soundPack = 'classic_wood', volume = 0.8) {
        if (!gameSettings.enableSound || soundPack === 'silent' || volume <= 0) return;
        const ctx = this.getContext();
        if (!ctx) return;
        const now = ctx.currentTime;
        const master = ctx.createGain();
        master.gain.setValueAtTime(volume, now);
        master.connect(ctx.destination);
        const osc1 = ctx.createOscillator();
        const osc2 = ctx.createOscillator();
        const gain = ctx.createGain();
        osc1.type = 'sawtooth'; osc2.type = 'sawtooth';
        osc1.frequency.setValueAtTime(150, now);
        osc2.frequency.setValueAtTime(158, now);
        gain.gain.setValueAtTime(0.5, now);
        gain.gain.exponentialRampToValueAtTime(0.01, now + 0.35);
        osc1.connect(gain); osc2.connect(gain); gain.connect(master);
        osc1.start(now); osc2.start(now);
        osc1.stop(now + 0.36); osc2.stop(now + 0.36);
    }
};

function applyBoardAppearanceSettings() {
    const boardEl = document.getElementById('chessboard');
    if (!boardEl) return;

    const theme = gameSettings.boardTheme || 'wood_walnut';
    const selectedTex = document.getElementById('select-square-texture')?.value || gameSettings.squareTexture;

    if (theme !== 'custom' && BOARD_THEME_PRESETS[theme]) {
        gameSettings.customLightSquare = BOARD_THEME_PRESETS[theme].light;
        gameSettings.customDarkSquare = BOARD_THEME_PRESETS[theme].dark;
        if (!selectedTex || selectedTex === 'none' || selectedTex === BOARD_THEME_PRESETS[theme].texture) {
            gameSettings.squareTexture = BOARD_THEME_PRESETS[theme].texture;
        } else {
            gameSettings.squareTexture = selectedTex;
        }
    } else if (selectedTex) {
        gameSettings.squareTexture = selectedTex;
    }

    const lightInput = document.getElementById('setting-custom-light-square');
    const darkInput = document.getElementById('setting-custom-dark-square');
    const themeSelect = document.getElementById('select-board-theme');
    const textureSelect = document.getElementById('select-square-texture');

    if (themeSelect && themeSelect.value !== theme) {
        themeSelect.value = theme;
    }
    if (lightInput && gameSettings.customLightSquare) {
        lightInput.value = gameSettings.customLightSquare;
    }
    if (darkInput && gameSettings.customDarkSquare) {
        darkInput.value = gameSettings.customDarkSquare;
    }
    if (textureSelect && gameSettings.squareTexture) {
        textureSelect.value = gameSettings.squareTexture;
    }

    boardEl.setAttribute('data-board-theme', theme);
    boardEl.setAttribute('data-square-texture', gameSettings.squareTexture || 'none');
    boardEl.setAttribute('data-grid-style', gameSettings.gridLineStyle || 'subtle');

    document.documentElement.style.setProperty('--sq-light', gameSettings.customLightSquare || '#f0d9b5');
    document.documentElement.style.setProperty('--sq-dark', gameSettings.customDarkSquare || '#b58863');

    document.querySelectorAll('.square .piece-svg, .square .piece').forEach(p => {
        p.classList.add('piece');
        p.setAttribute('data-piece-texture', gameSettings.pieceTexture || 'smooth');
        p.setAttribute('data-piece-set', gameSettings.pieceSet || 'wood_3d_real');
    });

    if (typeof renderBoard === 'function') {
        renderBoard();
    }
    if (typeof renderSettingsPreviewBoard === "function") renderSettingsPreviewBoard();
}

