function getPieceSvg(pieceKey, setStyle = (gameSettings.pieceSet || 'wood_3d_real')) {
    if (PIECE_SETS[setStyle] && PIECE_SETS[setStyle][pieceKey]) {
        return PIECE_SETS[setStyle][pieceKey];
    }
    return PIECE_SVGS[pieceKey] || (PIECE_SETS['wood_3d_real'][pieceKey] || '');
}


