function appendPromptTemplate(templateText) {
    const qEl = document.getElementById('mentor-custom-question');
    if (!qEl) return;
    const curVal = qEl.value.trim();
    if (!curVal) {
        qEl.value = templateText;
    } else {
        qEl.value = curVal + "\n\n" + templateText;
    }
    qEl.focus();
}

function initAccountCardToggle() {
    const card = document.getElementById('account-card');
    const header = document.getElementById('account-card-header');
    if (!card || !header) return;

    header.addEventListener('click', (e) => {
        if (e.target.tagName === 'BUTTON' && e.target.id !== 'btn-toggle-account') return;
        card.classList.toggle('collapsed');
    });
}

function initSidebarResizer() {
    const resizer = document.getElementById('sidebar-resizer');
    const sidebar = document.querySelector('.sidebar-section');
    if (!resizer || !sidebar) return;

    let isDragging = false;
    let startX = 0;
    let startWidth = 0;

    resizer.addEventListener('mousedown', (e) => {
        isDragging = true;
        startX = e.clientX;
        startWidth = sidebar.offsetWidth;
        resizer.classList.add('dragging');
        document.body.style.cursor = 'col-resize';
        document.body.style.userSelect = 'none';
    });

    document.addEventListener('mousemove', (e) => {
        if (!isDragging) return;
        const deltaX = startX - e.clientX;
        const newWidth = Math.max(320, Math.min(window.innerWidth * 0.75, startWidth + deltaX));
        sidebar.style.width = `${newWidth}px`;
    });

    document.addEventListener('mouseup', () => {
        if (isDragging) {
            isDragging = false;
            resizer.classList.remove('dragging');
            document.body.style.cursor = '';
            document.body.style.userSelect = '';
        }
    });
}

// ==========================================
// 💾 GAME & FEN/PGN MANAGER LOGIC
// ==========================================
let savedGames = [];

function loadSavedGamesFromStorage() {
    const saved = localStorage.getItem('chess_saved_games');
    if (saved) {
        try {
            savedGames = JSON.parse(saved);
        } catch (e) {
            savedGames = [];
        }
    }
}

function saveSavedGamesToStorage() {
    localStorage.setItem('chess_saved_games', JSON.stringify(savedGames));
}

function openGameManagerModal() {
    const modal = document.getElementById('game-manager-modal');
    if (!modal) return;

    if (!isAutoPaused) {
        isAutoPaused = true;
        updatePauseResumeButtonUI();
        if (autoMoveTimer) {
            clearTimeout(autoMoveTimer);
            autoMoveTimer = null;
        }
    }

    loadSavedGamesFromStorage();
    renderSavedGamesList();

    const fenText = document.getElementById('fen-input-text');
    if (fenText) fenText.value = currentFen;

    generateCurrentPgnText();

    modal.classList.remove('hidden');
}

function closeGameManagerModal() {
    const modal = document.getElementById('game-manager-modal');
    if (modal) modal.classList.add('hidden');
}

function initManagerSubtabs() {
    document.querySelectorAll('.subtab-btn').forEach(btn => {
        btn.addEventListener('click', () => {
            document.querySelectorAll('.subtab-btn').forEach(b => b.classList.remove('active'));
            document.querySelectorAll('.subtab-content').forEach(c => c.classList.remove('active'));
            btn.classList.add('active');
            const target = document.getElementById(btn.dataset.subtab);
            if (target) target.classList.add('active');
        });
    });
}

function saveCurrentGame() {
    const titleInput = document.getElementById('save-game-title');
    const notesInput = document.getElementById('save-game-notes');
    const title = (titleInput && titleInput.value.trim()) || `Game - ${new Date().toLocaleDateString()} ${new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}`;
    const notes = notesInput ? notesInput.value.trim() : '';

    const newGame = {
        id: 'game_' + Date.now(),
        title: title,
        date: new Date().toLocaleString(),
        fen: currentFen,
        moves: [...moveHistory],
        notes: notes
    };

    savedGames.unshift(newGame);
    saveSavedGamesToStorage();

    // Also persist into the active profile's history so it appears in the History tab
    const prof = getActiveProfile();
    if (prof) {
        if (!prof.history) prof.history = [];
        const eventId = `evt_saved_${Date.now()}`;
        const eventMoves = [];
        let parentId = null;
        (moveHistory || []).forEach((san, mIdx) => {
            const mNum = Math.floor(mIdx / 2) + 1;
            const mColor = (mIdx % 2 === 0) ? 'w' : 'b';
            const nodeId = `node_${eventId}_${mIdx+1}`;
            const uci = (moveStackUci && moveStackUci[mIdx]) ? moveStackUci[mIdx] : san;
            eventMoves.push({
                id: nodeId,
                event_id: eventId,
                profile_id: prof.id,
                move_number: mNum,
                color: mColor,
                move_san: san,
                move_uci: uci,
                fen: (mIdx === moveHistory.length - 1) ? currentFen : '',
                parent_id: parentId,
                branch_id: 'mainline',
                leaf_termination: null,
                per_move_analysis: {
                    stockfish_eval: '+0.0',
                    eval_delta: 0.05,
                    best_move_uci: uci,
                    best_move_san: san,
                    move_classification: 'Good',
                    six_aspect_flags: {
                        offensive_creation: false,
                        offensive_execution: false,
                        offensive_yield: 0,
                        defensive_prevention: false,
                        defensive_failure: false,
                        defensive_damage: 0
                    },
                    tactical_category: 'saved_game',
                    tactical_sub_category: 'custom'
                },
                stockfish_analysis_status: 'ANALYZED',
                mentor_analysis_status: 'ANALYZED'
            });
            parentId = nodeId;
        });

        prof.history.unshift({
            id: eventId,
            type: 'game',
            title: title,
            result: 'completed',
            startedAt: new Date().toISOString(),
            endedAt: new Date().toISOString(),
            startingFen: startFen || "rnbqkbnr/pppppppp/8/8/8/8/PPPPPPPP/RNBQKBNR w KQkq - 0 1",
            goal: notes || null,
            opponent: (gameSettings && gameSettings.blackPlayerMode === 'manual') ? 'Human' : 'Stockfish',
            totalNodes: eventMoves.length,
            moves: eventMoves
        });
        prof.gamesPlayed = (prof.gamesPlayed || 0) + 1;
        saveUserProfilesToStorage();
        if (typeof renderProfileHistoryTab === 'function') renderProfileHistoryTab();
    }

    renderSavedGamesList();

    if (titleInput) titleInput.value = '';
    if (notesInput) notesInput.value = '';
    alert('Game saved to library and profile history successfully!');
}

function renderSavedGamesList() {
    const listEl = document.getElementById('saved-games-list');
    if (!listEl) return;
    listEl.innerHTML = '';

    const prof = getActiveProfile();
    const profHistory = (prof && prof.history) ? prof.history : [];

    const allGames = [];
    (savedGames || []).forEach(g => {
        allGames.push({
            id: g.id,
            title: g.title,
            date: g.date || 'Custom',
            movesCount: g.moves ? g.moves.length : 0,
            notes: g.notes || 'Saved Custom Game',
            isSavedGame: true,
            rawGame: g
        });
    });

    profHistory.forEach(ev => {
        allGames.push({
            id: ev.id,
            title: ev.title,
            date: ev.startedAt ? new Date(ev.startedAt).toLocaleDateString() : 'Recent',
            movesCount: ev.moves ? ev.moves.length : 0,
            notes: `${(ev.type || 'game').toUpperCase()} • Result: ${ev.result || 'Finished'}${ev.goal ? ' • Goal: ' + ev.goal : ''}`,
            isSavedGame: false,
            rawEvent: ev
        });
    });

    if (allGames.length === 0) {
        listEl.innerHTML = `<p class="placeholder-text">No recorded games yet for ${prof.name}. Play a game or save your current game above!</p>`;
        return;
    }

    allGames.forEach(g => {
        const card = document.createElement('div');
        card.className = 'saved-game-card';
        card.innerHTML = `
            <div class="saved-game-info">
                <span class="saved-game-title">${g.title}</span>
                <span class="saved-game-meta">📅 ${g.date} | ♟️ ${g.movesCount} moves | 📝 ${g.notes}</span>
            </div>
            <div class="saved-game-actions">
                <button class="btn btn-secondary btn-sm" data-action="load">▶️ Load</button>
                ${g.isSavedGame ? `<button class="btn btn-secondary btn-sm" data-action="delete">🗑️</button>` : ''}
            </div>
        `;

        card.querySelector('[data-action="load"]').addEventListener('click', async () => {
            if (g.isSavedGame) {
                await loadSavedGame(g.id);
            } else if (g.rawEvent) {
                await loadProfileEventToBoard(g.rawEvent);
            }
            const modal = document.getElementById('game-manager-modal');
            if (modal) modal.classList.add('hidden');
        });

        if (g.isSavedGame) {
            const delBtn = card.querySelector('[data-action="delete"]');
            if (delBtn) delBtn.addEventListener('click', () => deleteSavedGame(g.id));
        }

        listEl.appendChild(card);
    });
}

async function loadProfileEventToBoard(ev) {
    if (!ev || !ev.moves || ev.moves.length === 0) return;
    if (typeof snapshotLiveGameIfNeeded === 'function') snapshotLiveGameIfNeeded();
    moveHistory = [];
    moveStackUci = [];
    startFen = ev.startingFen || "rnbqkbnr/pppppppp/8/8/8/8/PPPPPPPP/RNBQKBNR w KQkq - 0 1";
    currentFen = startFen;

    const mainlineMoves = ev.moves.filter(m => m.branch_id === 'mainline');
    mainlineMoves.forEach(m => {
        moveHistory.push(m.move_san);
        moveStackUci.push(m.move_uci);
    });

    parseFenToState(currentFen);
    initBoard();
    renderBoard();
    renderMoveHistoryTable();
    await updatePositionEvaluation();
}

async function loadSavedGame(gameId) {
    const game = savedGames.find(g => g.id === gameId);
    if (!game) return;
    if (typeof snapshotLiveGameIfNeeded === 'function') snapshotLiveGameIfNeeded();

    if (game.moves && game.moves.length > 0) {
        moveHistory = [];
        moveStackUci = [];
        currentFen = "rnbqkbnr/pppppppp/8/8/8/8/PPPPPPPP/RNBQKBNR w KQkq - 0 1";
        parseFenToState(currentFen);

        for (let m of game.moves) {
            moveHistory.push(m);
        }
        await updatePositionEvaluation();
    } else if (game.fen) {
        currentFen = game.fen;
        moveHistory = [];
        moveStackUci = [];
        await updatePositionEvaluation();
    }
    closeGameManagerModal();
    alert(`Loaded game: "${game.title}"`);
}

async function exportSavedGamePgn(gameId) {
    const game = savedGames.find(g => g.id === gameId);
    if (!game) return;

    try {
        const resp = await fetch('/api/pgn/export', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                moves: game.moves || [],
                fen: game.fen || null,
                headers: {
                    Event: game.title,
                    Site: "Chess AI Mentor Library"
                }
            })
        });
        const data = await resp.json();
        if (data.pgn) {
            const blob = new Blob([data.pgn], { type: 'text/plain;charset=utf-8' });
            const url = URL.createObjectURL(blob);
            const a = document.createElement('a');
            a.href = url;
            a.download = `${game.title.replace(/[^a-z0-9]/gi, '_')}.pgn`;
            document.body.appendChild(a);
            a.click();
            document.body.removeChild(a);
            URL.revokeObjectURL(url);
        }
    } catch (e) {
        alert('Failed to export PGN: ' + e.message);
    }
}

function deleteSavedGame(gameId) {
    if (!confirm('Are you sure you want to delete this saved game?')) return;
    savedGames = savedGames.filter(g => g.id !== gameId);
    saveSavedGamesToStorage();
    renderSavedGamesList();
}

function copyFenToClipboard() {
    const fenText = document.getElementById('fen-input-text').value;
    navigator.clipboard.writeText(fenText).then(() => {
        alert('FEN copied to clipboard!');
    }).catch(() => {
        alert('Copied FEN text.');
    });
}

async function loadFenFromInput() {
    const fenVal = document.getElementById('fen-input-text').value.trim();
    if (!fenVal) {
        alert('Please enter a valid FEN string.');
        return;
    }
    try {
        const resp = await fetch('/api/board/evaluate', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ fen: fenVal })
        });
        const data = await resp.json();

        startFen = data.fen;
        currentFen = data.fen;
        legalMoves = data.legal_moves || [];
        parseFenToState(currentFen);
        moveHistory = [];
        moveStackUci = [];
        lastMoveSquares = [];
        selectedSquare = null;

        renderMoveHistoryTable();
        renderBoard();
        updateUndoButtonState();
        closeGameManagerModal();
        alert('FEN loaded onto board successfully!');
    } catch (e) {
        alert('Invalid FEN string: ' + e.message);
    }
}

async function generateCurrentPgnText() {
    const pgnArea = document.getElementById('pgn-input-text');
    if (!pgnArea) return;

    const activeProf = (typeof getActiveProfile === 'function') ? getActiveProfile() : { name: 'Player' };
    const profileName = activeProf.name || 'Human Player';

    const wIsAuto = (gameSettings.whitePlayerMode === 'auto');
    const bIsAuto = (gameSettings.blackPlayerMode === 'auto');

    let whiteHeader = wIsAuto ? `Stockfish Level ${gameSettings.whiteDifficulty}` : profileName;
    let blackHeader = bIsAuto ? `Stockfish Level ${gameSettings.blackDifficulty}` : (!wIsAuto ? 'Black' : profileName);

    try {
        const resp = await fetch('/api/pgn/export', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                moves: moveHistory,
                headers: {
                    White: whiteHeader,
                    Black: blackHeader
                }
            })
        });
        const data = await resp.json();
        if (data.pgn) {
            pgnArea.value = data.pgn;
        }
    } catch (e) {
        console.error('Failed to generate PGN:', e);
    }
}

function copyPgnToClipboard() {
    const pgnText = document.getElementById('pgn-input-text').value;
    if (!pgnText) return;
    navigator.clipboard.writeText(pgnText).then(() => {
        alert('PGN copied to clipboard!');
    }).catch(() => {
        alert('Copied PGN text.');
    });
}

function downloadPgnFile() {
    const pgnText = document.getElementById('pgn-input-text').value;
    if (!pgnText) {
        alert('No PGN text available to download.');
        return;
    }
    const blob = new Blob([pgnText], { type: 'text/plain;charset=utf-8' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `chess_game_${Date.now()}.pgn`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
}

async function loadPgnFromInput() {
    const pgnVal = document.getElementById('pgn-input-text').value.trim();
    if (!pgnVal) {
        alert('Please enter or upload valid PGN text.');
        return;
    }
    try {
        const resp = await fetch('/api/pgn/parse', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ pgn: pgnVal })
        });
        const data = await resp.json();

        if (data.san_moves && data.san_moves.length > 0) {
            moveHistory = [...data.san_moves];
            moveStackUci = [...data.uci_moves];
            currentFen = "rnbqkbnr/pppppppp/8/8/8/8/PPPPPPPP/RNBQKBNR w KQkq - 0 1";
            parseFenToState(currentFen);
            await updatePositionEvaluation();
            closeGameManagerModal();
            alert(`PGN game loaded successfully (${data.san_moves.length} moves).`);
        } else if (data.final_fen) {
            currentFen = data.final_fen;
            moveHistory = [];
            moveStackUci = [];
            await updatePositionEvaluation();
            closeGameManagerModal();
            alert('Loaded initial PGN position onto board.');
        } else {
            alert('No moves found in PGN.');
        }
    } catch (e) {
        alert('Failed to parse PGN: ' + e.message);
    }
}

function handlePgnFileUpload(e) {
    const file = e.target.files[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (evt) => {
        const content = evt.target.result;
        const pgnArea = document.getElementById('pgn-input-text');
        if (pgnArea) pgnArea.value = content;
        loadPgnFromInput();
    };
    reader.readAsText(file);
}

